 19	ProviderListeners logging_listeners()
 20	{
 21	    ProviderListeners listeners;
 22	    // Refused tool calls never reach a card or the activity list; the log is
 23	    // where a wrong call can be read afterwards.
 24	    listeners.refusal = [](const std::string& tool, const std::string& arguments, const std::string& code) {
 25	        BOOST_LOG_TRIVIAL(warning) << "Agent tool call refused (" << code << "): " << tool << " " << arguments.substr(0, 1024);
 26	    };
 27	    return listeners;
 28	}
