 45	AgentRuntime load_agent_runtime(AppConfig* config)
 46	{
 47	    AgentSettings settings;
 48	    settings.enabled       = configured_true(config, "enabled");
 49	    settings.cloud_consent = configured_true(config, "cloud_consent");
 50	    if (config != nullptr) {
 51	        settings.provider = config->get(kSection, "provider");
 52	        settings.model    = config->get(kSection, "model");
 53	    }
 54	    settings.api_key = load_provider_api_key(config, settings.provider.empty() ? "openai" : settings.provider);
 55	    AgentRuntime runtime = resolve_agent_runtime(settings, agent_endpoint_override(), &make_openai_http_transport, logging_listeners());
 56	    runtime.setup        = make_agent_setup(config);
 57	    return runtime;
 58	}
