 60	AgentSetupServicePtr make_agent_setup(AppConfig* config)
 61	{
 62	    // Committing is the only part of setup that touches the machine, so it
 63	    // lives here rather than in the GUI-free probe. Reaching this point means
 64	    // the user read what the dock says about the provider billing them and
 65	    // about the key staying on this machine, and chose to continue: that is
 66	    // the cloud consent load_agent_runtime() requires on the next launch.
 67	    auto commit = [config](const SetupCredentials& credentials) {
 68	        if (config == nullptr || credentials.provider.empty() || credentials.api_key.empty())
 69	            return false;
 70	        config->set(kSection, api_key_item_for(credentials.provider), credentials.api_key);
 71	        config->set(kSection, "provider", credentials.provider);
 72	        config->set(kSection, "enabled", "true");
 73	        config->set(kSection, "cloud_consent", "true");
 74	        if (!credentials.model.empty())
 75	            config->set(kSection, "model", credentials.model);
 76	        // Written now, not at the next routine save, so a crash after setup
 77	        // does not lose a key the user was just told is stored.
 78	        config->save();
 79	        return true;
 80	    };
 81	    return std::make_shared<ProviderKeySetup>(&make_openai_http_transport, std::move(commit), agent_endpoint_override());
 82	}
