 86	class AppConfigChatModelSource final : public IChatModelSource
 87	{
 88	public:
 89	    AppConfigChatModelSource(AppConfig* config, std::function<void(std::function<void()>)> post)
 90	        : m_config(config), m_post(std::move(post)), m_cancelled(std::make_shared<std::atomic<bool>>(false))
 91	    {}
 92	    // A list still on its way is dropped rather than delivered to a host
 93	    // that is gone.
 94	    ~AppConfigChatModelSource() override { *m_cancelled = true; }
 95	
 96	    // Read each time: setup may have stored a key since the last turn.
 97	    std::vector<std::string> configured_providers() const override
 98	    {
 99	        std::vector<std::string> providers;
100	        if (!configured_true(m_config, "enabled") || !configured_true(m_config, "cloud_consent"))
101	            return providers;
102	        for (const ProviderProfile& profile : provider_profiles())
103	            if (!load_provider_api_key(m_config, profile.id).empty())
104	                providers.push_back(profile.id);
105	        return providers;
106	    }
107	
108	    std::string default_provider() const override
109	    {
110	        const std::string provider = m_config == nullptr ? std::string() : m_config->get(kSection, "provider");
111	        return provider.empty() ? "openai" : provider;
112	    }
113	
114	    AgentServicePtr make_agent(const ChatModelChoice& choice) override
115	    {
116	        const ProviderProfile* row = profile_for(choice.provider);
117	        const std::string      key = load_provider_api_key(m_config, choice.provider);
118	        if (row == nullptr || key.empty())
119	            return nullptr;
120	        ProviderProfile profile = *row;
121	        profile.effort          = choice.effort;
122	        return make_provider_agent(profile, key, choice.model, agent_endpoint_override(), make_openai_http_transport(),
123	                                   logging_listeners());
124	    }
125	
126	    void list_models(const std::string& provider, ModelsDone done) override
127	    {
128	        const ProviderProfile* profile = profile_for(provider);
129	        const std::string      key     = load_provider_api_key(m_config, provider);
130	        if (profile == nullptr || key.empty()) {
131	            done(false, {});
132	            return;
133	        }
134	        fetch_model_list(*profile, key, agent_endpoint_override(), m_cancelled,
135	                         [post = m_post, done = std::move(done), provider](ModelListResult result) {
136	                             if (!result.ok)
137	                                 BOOST_LOG_TRIVIAL(warning) << "Agent model list for " << provider << ": " << result.error;
138	                             post([done, result = std::move(result)]() mutable { done(result.ok, std::move(result.models)); });
139	                         });
140	    }
141	
142	private:
143	    AppConfig*                                  m_config;
144	    std::function<void(std::function<void()>)>  m_post;
145	    std::shared_ptr<std::atomic<bool>>          m_cancelled;
146	};
