 91	export interface SetupApiKeyProps {
 92	  setup: SetupStatusPayload;
 93	  onCheck: (provider: string, apiKey: string) => void;
 94	  onCancel: () => void;
 95	  onBack: () => void;
 96	}
 97	
 98	export function SetupApiKey({ setup, onCheck, onCancel, onBack }: SetupApiKeyProps) {
 99	  const [provider, setProvider] = useState(DEFAULT_PROVIDER);
100	  const [key, setKey] = useState('');
101	  const [pasteAvailable, setPasteAvailable] = useState(false);
102	  const input = useRef<HTMLInputElement>(null);
103	
104	  // Clipboard reads are not granted in every embedded web view; the paste
105	  // shortcut appears only where it will actually work. Typing and the
106	  // platform's own paste always do.
107	  useEffect(() => {
108	    setPasteAvailable(
109	      typeof navigator !== 'undefined' && !!navigator.clipboard && typeof navigator.clipboard.readText === 'function',
110	    );
111	  }, []);
112	
113	  const checking = setup.phase === 'checking';
114	  const option = PROVIDERS.find((candidate) => candidate.id === provider)!;
115	
116	  const paste = () => {
117	    navigator.clipboard
118	      .readText()
119	      .then((text) => {
120	        setKey(text.trim());
121	        input.current?.focus();
122	      })
123	      .catch(() => {
124	        // Refused at the OS or view level: leave the field alone and let the
125	        // user paste the way they always could.
126	        input.current?.focus();
127	      });
128	  };
129	
130	  const submit = () => {
131	    if (!key.trim() || checking) return;
132	    onCheck(provider, key.trim());
133	  };
134	
135	  return (
136	    <div className="pane-state setup" data-testid="setup-api-key">
137	      <div className="setup-card">
138	        <SetupScreenTitle label="Your own API key" onBack={onBack} />
139	        <p>Billed by your provider, not JusPrin. Stored on this machine only.</p>
140	
141	        <div className="setup-tabs" role="tablist" aria-label="Provider">
142	          {PROVIDERS.map((candidate) => (
143	            <button
144	              key={candidate.id}
145	              role="tab"
146	              aria-selected={candidate.id === provider}
147	              className={candidate.id === provider ? 'setup-tab selected' : 'setup-tab'}
148	              disabled={!candidate.available}
149	              title={candidate.available ? undefined : `${candidate.label} support arrives in a later JusPrin release`}
150	              onClick={() => setProvider(candidate.id)}
151	            >
152	              {candidate.label}
153	            </button>
154	          ))}
155	        </div>
156	
157	        <div className="setup-key">
158	          <input
159	            ref={input}
160	            type="password"
161	            className="setup-key-input"
162	            aria-label={`${option.label} API key`}
163	            placeholder={option.placeholder}
164	            value={key}
165	            disabled={checking}
166	            onChange={(event) => setKey(event.target.value)}
167	            onKeyDown={(event) => {
168	              if (event.key === 'Enter') submit();
169	            }}
170	          />
171	          {pasteAvailable && (
172	            <button className="link" onClick={paste} disabled={checking}>
173	              paste
174	            </button>
175	          )}
176	        </div>
177	
178	        <div className="setup-actions">
179	          <button className="primary" onClick={submit} disabled={checking || key.trim().length === 0}>
180	            Check key
181	          </button>
182	          {checking && (
183	            <button className="link" onClick={onCancel}>
184	              Cancel
185	            </button>
186	          )}
187	          <SetupResult setup={setup} />
188	        </div>
189	
190	        <p className="footnote">
191	          Each chat starts on this provider’s recommended model. You can switch the model, or the provider, in any chat.
192	        </p>
193	      </div>
194	    </div>
195	  );
196	}
