198	function SetupResult({ setup }: { setup: SetupStatusPayload }) {
199	  if (setup.phase === 'checking') return <span className="setup-result">Checking…</span>;
200	  if (setup.phase === 'verified')
201	    return (
202	      <span className="setup-result ok" data-testid="setup-verified">
203	        <span className="jp-icon jp-icon-check" aria-hidden="true" /> replied in {seconds(setup.elapsedMs ?? 0)}
204	      </span>
205	    );
206	  if (setup.phase === 'error')
207	    return (
208	      <span className="setup-result error" role="alert" data-testid="setup-error">
209	        {setup.error?.message ?? 'The key could not be checked.'}
210	      </span>
211	    );
212	  return null;
213	}
