    43	class IAgentSetupService
    44	{
    45	public:
    46	    virtual ~IAgentSetupService() = default;
    47	
    48	    virtual bool busy() const = 0;
    49	
    50	    // Begins one verification. False when a check is already running, the
    51	    // credentials are incomplete, or this build has no adapter for the
    52	    // provider.
    53	    virtual bool start_check(const SetupCredentials& credentials) = 0;
    54	    virtual void cancel() = 0;
    55	
    56	    // Releases at most one finished outcome; called from the owner's tick.
    57	    virtual std::optional<SetupOutcome> poll() = 0;
    58	
    59	    // Persists credentials that have just been verified. Reports failure
    60	    // rather than pretending: a key that was not stored is a key the user
    61	    // will have to enter again next launch, and they are told so.
    62	    virtual bool commit(const SetupCredentials& credentials) = 0;
    63	};
