html=open(src).read()
inject=r'''<script>
(function(){
  var base='http://127.0.0.1:8792/';
  var log=function(o){fetch(base+'log?'+encodeURIComponent(JSON.stringify(o))).catch(function(){});};
  var hook=function(){var b=window.__jusprinBridge;if(!b){setTimeout(hook,50);return;}if(b.__hooked)return;var orig=b.deliver;
    b.deliver=function(env){var e=typeof env==='string'?JSON.parse(env):env;
      if(['setup_keys','setup_status','agent_status','bridge_error','assistant_failed'].indexOf(e.type)>=0)log({type:e.type,payload:e.payload});
      return orig.call(b,env);};b.__hooked=true;};
  hook();
  var byText=function(t){return Array.prototype.find.call(document.querySelectorAll('button'),function(x){return x.textContent.trim()===t;});};
  var setVal=function(el,v){var s=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;s.call(el,v);el.dispatchEvent(new Event('input',{bubbles:true}));};
  var run={
    openApiKey:function(){window.__jusprinTest.openSetup();setTimeout(function(){document.querySelector('[data-testid=setup-row-api-key]').click();setTimeout(function(){byText('Anthropic').click();},200);},200);},
    click:function(a){var b=byText(a);if(b)b.click();else log({missing:a});},
    type:function(a){var el=document.querySelector('.setup-key-input');setVal(el,a);},
    send:function(a){window.__jusprinTest.send(a);},
    back:function(){var b=document.querySelector('[aria-label="Back to setup options"]');if(b)b.click();},
    blur:function(){if(document.activeElement)document.activeElement.blur();}
  };
  var seen=0;
  setInterval(function(){fetch(base+'cmd.json?'+Date.now()).then(function(r){return r.json();}).then(function(c){
    if(c.seq>seen){seen=c.seq;try{run[c.op](c.arg);log({done:c.seq,op:c.op});}catch(err){log({err:String(err),op:c.op});}}}).catch(function(){});},400);
})();
</script>'''
i=html.index('<head>')+len('<head>')
open(dst,'w').write(html[:i]+inject+html[i:])
